using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Windows.Forms;using System.IO.Compression;using System.Text;
namespace GearLab {
 public static class AuditFixTests {
  static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
  static object Field(object o,string key){return o.GetType().GetField(key,Flags).GetValue(o);}
  static object Call(object o,string method,params object[] args){return o.GetType().GetMethod(method,Flags).Invoke(o,args);}
  public static int Run(string folder){Directory.CreateDirectory(folder);var checks=new List<string>();var errors=new List<string>();Action<bool,string> c=(ok,label)=>{if(!ok)throw new Exception(label);checks.Add(label);};try{
   foreach(int k in new[]{6,9,10}){var p=Engine.Starter(k);var before=Engine.Calculate(p);p.Overall=Math.Max(before.Width,before.Height)*1.2;c(Engine.FitOverall(p),"B01 feasible auto-fit "+k);var r=Engine.Calculate(p);c(r.Valid&&Math.Max(r.Width,r.Height)<=p.Overall+.001,"B01 actual geometry fits "+k);}
   for(int k=5;k<13;k++){var p=Engine.Starter(k);var r=Engine.Calculate(p);p.Overall=Math.Max(r.Width,r.Height)*1.2;bool fitted=Engine.FitOverall(p);var trial=Engine.Clone(p);if(k==7||k==11)trial.Radius=p.Overall/2-12;var probe=Engine.Calculate(trial);c(fitted&&Engine.Calculate(p).Valid,"B01 all new fit "+k+": "+string.Join(";",probe.Errors));var tiny=Engine.Clone(p);tiny.Overall=1;string saved=ReleaseSupport.Serialize(tiny);c(!Engine.FitOverall(tiny)&&ReleaseSupport.Serialize(tiny)==saved,"B01 failed fit preserves fields "+k);}
   using(var form=new MainForm()){
    ((Timer)Field(form,"animation")).Stop();var nums=(Dictionary<string,SafeNumber>)Field(form,"numbers");
    for(int k=0;k<4;k++){var p=Engine.Starter(k);Call(form,"Apply",p,p.AutoFit);c((bool)Call(form,"VisibleField","InputTorque")&&(bool)Call(form,"VisibleField","Efficiency"),"B05 load fields visible "+k);var cached=((Result)Field(form,"result")).Model;nums["InputTorque"].Commit(.5m);nums["Efficiency"].Commit(.8m);Call(form,"CommitAndCalculate");var r=(Result)Field(form,"result");c(r.Valid&&Math.Abs(r.Loads.OutputTorque-.5*r.Actual*.8)<1e-8,"B05 actual torque updates "+k);c(ReferenceEquals(cached,r.Model),"B05 loads reuse geometry "+k);}
    var worm=Engine.Starter(5);worm.Overall=100;Call(form,"Apply",worm,true);c(!nums["Module"].Enabled,"B04 auto module disabled");((CheckBox)Field(form,"auto")).Checked=false;c(nums["Module"].Enabled,"B04 manual module enabled");
    for(int k=0;k<13;k++){var p=Engine.Starter(k);Call(form,"Apply",p,p.AutoFit);((CheckBox)Field(form,"modelSettings")).Checked=true;Call(form,"RefreshFields");c((bool)Call(form,"VisibleField","ServiceFactor")==ReducerFieldPolicy.Strength(p),"B06 strength method applicability "+k);if(k>=5){c(!(bool)Call(form,"VisibleField","ModelCover")&&!(bool)Call(form,"VisibleField","ModelShaftExtension"),"B06 unsupported housing fields hidden "+k);}if(k==11)c(!(bool)Call(form,"VisibleField","Module")&&!(bool)Call(form,"VisibleField","PressureAngle"),"B06 magnetic fields");if(k==12)c(!(bool)Call(form,"VisibleField","OutputShaft"),"B06 rack output units");}
    ((IWorkspaceDocument)form).WorkspaceApproveClose();
   }
   foreach(int k in Enumerable.Range(0,13))foreach(var prop in typeof(Parameters).GetProperties().Where(f=>f.PropertyType==typeof(double)))foreach(double value in new[]{double.NaN,double.PositiveInfinity,double.NegativeInfinity}){var p=Engine.Starter(k);prop.SetValue(p,value,null);c(!Engine.Calculate(p).Valid,"B07 finite "+k+"/"+prop.Name+"/"+value);}
   for(int k=5;k<13;k++){var p=Engine.Starter(k);var r=Engine.Calculate(p);r.Model=CadBuilder.Build(r);foreach(int scope in new[]{1,2}){var subset=ReducerExportSelection.ForScope(r.Model,scope);c(subset.Parts.Count>0&&subset.Parts.Count<r.Model.Parts.Count,"B03 subset parts "+k+"/"+scope);if(scope==2)c(subset.Parts.All(PrintExport.Candidate),"B03 only printable parts "+k);foreach(string type in new[]{"svg","dxf","csv"}){p.ExportScope=r.P.ExportScope=0;string full=Path.Combine(folder,"k"+k+"-all."+type),part=Path.Combine(folder,"k"+k+"-scope"+scope+"."+type);ReleaseSupport.Export(r,type,full);r.P.ExportScope=scope;ReleaseSupport.Export(r,type,part);c(!File.ReadAllBytes(full).SequenceEqual(File.ReadAllBytes(part)),"B03 actual "+type+" scope "+k+"/"+scope);}}}
   var train=TransmissionTrain.Example();var doc=new RobotDocument();var joint=doc.Add(null);joint.BodyStyle=RobotBodyStyle.Открытая_рама;joint.BodyGenerator=null;double ratio=joint.Reduction,eta=joint.Efficiency;bool refused=false;try{RobotTrainIntegration.Apply(joint,train,train.Stages[0].Id);}catch{refused=true;}c(refused&&joint.TrainSettings==null&&joint.Reduction==ratio&&joint.Efficiency==eta,"B08 intermediate output rejected without mutation");RobotTrainIntegration.Apply(joint,train,train.Stages.Last().Id);c(Math.Abs(joint.Reduction-40)<1e-8&&Math.Abs(joint.Efficiency-.49)<1e-8,"B08 final output has correct path ratio and efficiency");
   train=TransmissionTrain.Example();train.Stages[0].Parameters=Engine.Starter(1);using(var form=new TrainDesignerForm(train)){Call(form,"Reload",new object[]{null});Call(form,"Calculate");var editor=(MainForm)Field(form,"editor");var nums=(Dictionary<string,SafeNumber>)Field(editor,"numbers");((CheckBox)Field(editor,"auto")).Checked=false;nums["Thickness"].Commit(10);Call(editor,"CommitAndCalculate");string zip=Path.Combine(folder,"fresh-chain.zip");form.ExportStlFile(zip);var state=(TrainSolution)Field(form,"solution");var current=(TransmissionTrain)Field(form,"document");c(state.States[current.Stages[0].Id].Result.P.Thickness==10,"B02 exports captured edited thickness");using(var archive=ZipFile.OpenRead(zip)){var entry=archive.Entries.First(e=>e.Name.StartsWith(current.Stages[0].Id)&&e.Name.Contains("_DRIVE_GEAR"));using(var s=entry.Open())using(var rd=new BinaryReader(s)){rd.ReadBytes(80);uint n=rd.ReadUInt32();double lo=double.MaxValue,hi=double.MinValue;for(int t=0;t<n;t++){rd.ReadBytes(12);for(int v=0;v<3;v++){rd.ReadSingle();rd.ReadSingle();double z=rd.ReadSingle();lo=Math.Min(lo,z);hi=Math.Max(hi,z);}rd.ReadUInt16();}c(Math.Abs(hi-lo-10)<1e-6,"B02 actual STL gear is 10mm");}}byte[] original=File.ReadAllBytes(zip);nums["Thickness"].Text="ошибка";refused=false;try{form.ExportStlFile(zip);}catch{refused=true;}c(refused&&original.SequenceEqual(File.ReadAllBytes(zip)),"B02 invalid pending edit preserves existing export");editor.WorkspaceApproveClose();form.WorkspaceApproveClose();}
   c(ReleaseSupport.HelpText.Contains("13 типов")&&ReleaseSupport.HelpText.Contains("СТУПЕНИ")&&!ReleaseSupport.HelpText.Contains("НОВОЕ В 1.5"),"B09 current complete help");
  }catch(Exception ex){errors.Add(ex.GetBaseException().ToString());}File.WriteAllText(Path.Combine(folder,"audit-fixes-results.json"),CADDocument.Serializer().Serialize(new{Passed=errors.Count==0,Checks=checks.Count,Assertions=checks,Errors=errors}),Encoding.UTF8);return errors.Count==0?0:1;}
 }
}

